using UnityEngine;
namespace PivotAscent { [RequireComponent(typeof(SpriteRenderer))] public sealed class PivotVisual : MonoBehaviour { void Awake() { var renderer = GetComponent<SpriteRenderer>(); if (renderer.sprite == null) renderer.sprite = Sprite.Create(Texture2D.whiteTexture, new Rect(0, 0, 1, 1), new Vector2(.5f, .5f)); renderer.color *= 1.6f; var outline = gameObject.AddComponent<LineRenderer>(); outline.useWorldSpace = false; outline.loop = true; outline.positionCount = 4; outline.SetPositions(new[] { new Vector3(-.5f, -.5f), new Vector3(-.5f, .5f), new Vector3(.5f, .5f), new Vector3(.5f, -.5f) }); outline.startWidth = outline.endWidth = .055f; outline.material = new Material(Shader.Find("Sprites/Default")); outline.startColor = outline.endColor = renderer.color; } } }
